mapper.select:
select re.`id`, re.`product_id`, re.`name`, re.`icon`, re.`sort`, re.`remark`, re.`builtin`, re.`enabled`, re.`tenant`, re.`deleted`, re.`create_by`, re.`create_time`, re.`update_by`, re.`update_time`, ure.`user_id` from `role` re inner join `user_role` ure on ure.`role_id` = re.`id` where ure.`user_id` in
#{id}
and re.`enabled` = true order by re.`sort` asc, re.`id` desc
